</code></pre> <pre><code>// Create an entry endpoint
val client = EntryEndpoint(URI.create("http://example.com/api/"))

// Create child endpoint
val contacts = CollectionEndpointImpl(client, "contacts", Contact::class.java)
</code></pre> <pre><code>// Create an entry endpoint
