// Upload from a file
avatar.uploadFrom("new-avatar.jpg")

// Or upload from a stream
FileInputStream("new-avatar.jpg").use { fileStream -&gt;
    avatar.uploadFrom(fileStream, mimeType = "image/jpeg")
}
</code></pre> <pre><code>const avatar = new BlobEndpoint(client, "users/123/avatar");

// Download binary data
